      scoreCards.splice(1, 0, { label: 'Framework Application', val: result.scores.frameworkUsage, icon: '📐' });
      scoreCards.splice(2, 0, { label: 'Strategic Insight', val: result.scores.strategicInsight ?? 0, icon: '♟️' });
