          communicationClarity: { type: Type.NUMBER, description: "Score 1-5" },
          mathAndReasoning: { type: Type.NUMBER, description: "Score 1-5 (Optional, for Guesstimates)" },
          strategicInsight: { type: Type.NUMBER, description: "Score 1-5 (Optional, for Strategy)" },
          userUnderstanding: { type: Type.NUMBER, description: "Score 1-5 (Optional, for Product Design)" },
          prioritizationClarity: { type: Type.NUMBER, description: "Score 1-5 (Optional, for Product Design)" },
          behavioralStructure: { type: Type.NUMBER, description: "Score 1-5 (STAR Framework usage)" },
          introspection: { type: Type.NUMBER, description: "Score 1-5 (Depth of reflection)" },
          leadershipCompetencies: { type: Type.NUMBER, description: "Score 1-5 (Leadership demonstrated)" },
          finalScore: { type: Type.NUMBER, description: "Total Score 0-100" },
        },
        required: ["structuredThinking", "frameworkUsage", "communicationClarity", "finalScore"]
      },
      improvementSuggestions: { type: Type.STRING, description: "Brutal feedback bullets." }
    },
    required: ["rootCauseSummary", "reasoningSteps", "recommendedActions", "scores", "improvementSuggestions"]
  };

  // Define Category-Specific Grading Criteria
  let criteria = "";
  if (category === 'RCA') {
      criteria = `
      - Problem structuring (MECE reasoning?)
      - Clarity of hypothesis tree
      - Prioritization & reasoning
      - Identification of actual root cause
      - Actionable next steps
      `;
  } else if (category === 'Product Design') {
      criteria = `
      - User segmentation (Specific?)
      - Clear problem definition
      - Sharp insights (Not generic)
      - End-to-end solution thinking
      - Metrics (Activation, Engagement, Retention)
      - Tradeoffs & edge cases
      `;
  } else if (category === 'Guesstimate') {
      criteria = `
      - Clear assumptions (Defensible?)
      - Logical breakdown (MECE tree?)
      - Math sanity (Correct calculations?)
      - Final summary with confidence
      `;
  } else if (category === 'Strategy') {
      criteria = `
      - Understanding of market, competition, moat
      - Prioritization (Strategic focus)
      - North star metric clarity
      - Risks & mitigation
      - Business impact reasoning
      `;
  } else if (category === 'Behavioral') {
      criteria = `
      - STAR Framework adherence (Situation, Task, Action, Result)
      - Ownership mindset ("I" vs "We")
      - Data-driven results
      - Introspection & Learning
      `;
  }

  try {
    const prompt = `
      ACT AS A BRUTALLY HONEST, HYPER-EXPERIENCED SENIOR PM (ex-FAANG, ex-startup).
      You are evaluating a candidate’s answer for a ${category} interview.
      Your job is to score the candidate harshly, expose weaknesses with zero sugarcoating, and reward only exceptional clarity.

      **EVALUATION RULES:**
      1. **Be Brutal**: Do not be polite. Do not soften feedback. Tone = Direct, cold, fact-based.
      2. **Score Harshly**: 
         - 0-3/5: Assumptions without structure, vague statements, no data.
         - 4/5: Good, standard answer.
         - 5/5: Exceptional, MECE, crisp, metrics-first. (Reserved for the top 1%)

      **CATEGORY CRITERIA (${category}):**
      ${criteria}

      **OUTPUT INSTRUCTIONS (JSON):**
      1. **rootCauseSummary**: The actual correct solution/summary of the case.
      2. **reasoningSteps**: "What a Strong Answer WOULD Have Done". List exact structural steps.
      3. **improvementSuggestions**: "Brutal Feedback". Write 5-10 bullets of harsh critique. (e.g., "Your reasoning is superficial.", "You missed the core insight.").
      4. **scores**: Rate strictly based on the 1-5 scale (where 1=Poor, 5=Exceptional).
      5. **finalScore**: 0-100 based on overall impression.

      Return the result strictly in JSON format matching the schema.
    `;

    const response = await chat.sendMessage({
      message: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: evaluationSchema
      }
    });

    const text = response.text || "{}";
    return JSON.parse(text) as EvaluationResult;
  } catch (error) {
    console.error("Error generating evaluation:", error);
    return {
      rootCauseSummary: "Error retrieving evaluation.",
      reasoningSteps: [],
      recommendedActions: [],
      scores: {
        structuredThinking: 0,
        frameworkUsage: 0,
        communicationClarity: 0,
        finalScore: 0
      },
      improvementSuggestions: "Please try again."
    };
  }
};

